(* ^safe-9ved ^safe-r5ye ^safe-ohen: operation candidates, descriptor facts and scope controls. *)
let thread thread () = Eio_main.run (fun _ -> Thread.join thread)
let domain domain () = Eio_main.run (fun _ -> ignore (Domain.join domain))
let read () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [] 0 in ignore (Unix.read fd (Bytes.create 1) 0 1))
let write () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [Unix.O_WRONLY] 0 in ignore (Unix.write fd (Bytes.create 1) 0 1))
let nonblock () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [Unix.O_NONBLOCK] 0 in ignore (Unix.read fd (Bytes.create 1) 0 1))
let cleared () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [Unix.O_NONBLOCK] 0 in Unix.clear_nonblock fd; ignore (Unix.read fd (Bytes.create 1) 0 1))
let set () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [] 0 in Unix.set_nonblock fd; ignore (Unix.read fd (Bytes.create 1) 0 1))
let unknown fd () = Eio_main.run (fun _ -> ignore (Unix.read fd (Bytes.create 1) 0 1))
let native ~pool () = Eio_main.run (fun _ -> ignore (Ox_blocking.run ~pool (fun () -> let fd = Unix.openfile "unused" [] 0 in ignore (Unix.read fd (Bytes.create 1) 0 1))))
let transfer fn () = Eio_main.run (fun _ -> fn (fun () -> Unix.sleepf 0.1))
let unrelated fn () = Eio_main.run (fun env -> ignore (fn env); ignore env#clock)
let partial fd () = Eio_main.run (fun _ -> let _dormant = Unix.read fd (Bytes.create 1) in ())
let conditional flag () = Eio_main.run (fun _ -> let fd = Unix.openfile "unused" [Unix.O_NONBLOCK] 0 in if flag then Unix.clear_nonblock fd; ignore (Unix.read fd (Bytes.create 1) 0 1))
let imported_native ~pool () = Eio_main.run (fun _ -> ignore (Controls.run_native ~pool (fun () -> Unix.sleepf 0.01)))
let imported_partial () = Eio_main.run (fun _ -> let _dormant = Controls.run_native (fun () -> Unix.sleepf 0.01) in ())
